-- Create "concept_mastery" table
CREATE TABLE "concept_mastery" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), "engine_section_id" character varying NOT NULL, "node_id" character varying NOT NULL, "state" character varying NOT NULL, "score" double precision NULL, "attempts" bigint NOT NULL DEFAULT 0, "last_attempt_at" timestamptz NULL, "structure_digest" character varying NULL, "structure_chunks" bigint NULL, "student_id" uuid NOT NULL, "academic_session_id" uuid NOT NULL, "content_item_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "concept_mastery_academic_sessions_academic_session" FOREIGN KEY ("academic_session_id") REFERENCES "academic_sessions" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "concept_mastery_content_items_content_item" FOREIGN KEY ("content_item_id") REFERENCES "content_items" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "concept_mastery_students_student" FOREIGN KEY ("student_id") REFERENCES "students" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "concept_mastery_attempts_sane" CHECK (attempts >= 0), CONSTRAINT "concept_mastery_score_in_unit" CHECK ((score IS NULL) OR ((score >= (0)::double precision) AND (score <= (1)::double precision))), CONSTRAINT "concept_mastery_state_known" CHECK ((state)::text = ANY ((ARRAY['read'::character varying, 'missed'::character varying, 'shaky'::character varying, 'known'::character varying])::text[])));
-- Create index "conceptmastery_academic_session_id" to table: "concept_mastery"
CREATE INDEX "conceptmastery_academic_session_id" ON "concept_mastery" ("academic_session_id");
-- Create index "conceptmastery_content_item_id_engine_section_id" to table: "concept_mastery"
CREATE INDEX "conceptmastery_content_item_id_engine_section_id" ON "concept_mastery" ("content_item_id", "engine_section_id");
-- Create index "conceptmastery_student_id_acad_3d9a6a27530cf45a32536ca51c6876a1" to table: "concept_mastery"
CREATE UNIQUE INDEX "conceptmastery_student_id_acad_3d9a6a27530cf45a32536ca51c6876a1" ON "concept_mastery" ("student_id", "academic_session_id", "content_item_id", "node_id");
